Task-116534ba: Diagonal trail transformation

DEMO Analysis:
When two values share the same diagonal (r-c or r+c), they split it:
- First value (by input order): gets cells from diagonal start to (second's first row - 1)
- Second value: gets cells from its first row to diagonal end
"""

import copy

def transform(grid):
    """Transform grid, adding trails for non-background values."""
    bg = grid[0][0]

    # Collect non-bg cells by value
    cells = {}
    for r, row in enumerate(grid):
        for c, val in enumerate(row):
            if val != bg:
                cells.setdefault(val, []).append((r, c))

    output = copy.deepcopy(grid)

    for val, positions in cells.items():
        # Check diagonal type
        rcs = [r - c for r, c in positions]
        rcsums = [r + c for r, c in positions]

        if all(x == rcs[0] for x in rcs):
            diag_type, diag_const = "r-c", rcs[0]
        elif all(x == rcsums[0] for x in rcsums):
            diag_type, diag_const = "r+c", rcsums[0]
        else:
